var scene = get_tree().current_scene
Engine.max_fps = 120
var angles = [-108.0,-144.0,180.0,144.0,108.0,72.0,36.0,0.0,-36.0,-72.0]
var before = scene.log_rows.size()
var frames_before = Engine.get_frames_drawn()
var start_us = Time.get_ticks_usec()
for trial in range(60):
	var angle = deg_to_rad(angles[trial % 10])
	var vector = Vector2(cos(angle), -sin(angle)) * 0.95
	for values in [vector, Vector2.ZERO]:
		for axis in [JOY_AXIS_RIGHT_X,JOY_AXIS_RIGHT_Y]:
			var event = InputEventJoypadMotion.new()
			event.device = 0
			event.axis = axis
			event.axis_value = values.x if axis == JOY_AXIS_RIGHT_X else values.y
			Input.parse_input_event(event)
		for frame in range(3):
			await get_tree().process_frame
return {"new_rows":scene.log_rows.size()-before,"rows_total":scene.log_rows.size(),"samples_retained":scene.samples.size(),"samples_ms":scene.samples,"rows":scene.log_rows.slice(before),"p95_ms":scene._pct(0.95),"frames":Engine.get_frames_drawn()-frames_before,"elapsed_ms":(Time.get_ticks_usec()-start_us)/1000.0,"static_memory_bytes":Performance.get_monitor(Performance.MEMORY_STATIC)}
